:root { --sk-tile-padding: 2em 2.5em; --tile-custom-gap: 1em; }
@media only screen and (max-width: 1068px) {
  :root { --sk-tile-padding: 2em 1.5em; }
}
body[data-color-scheme="light"] { --bg-light-override: #f5f5f7; --bg-fill: #fff; --bg-fill-invert: #000; --card-border-color: #d8d8d8; }
body[data-color-scheme="dark"] { --bg-light-override: #161617; --bg-fill: #000; --bg-fill-invert: #fff; --card-border-color: #222; }
.bg-light { background-color: var(--bg-light-override); }
.bg-fill { background-color: var(--bg-fill); }
.bg-fill .tile { background-color: var(--bg-light-override); }
.sf-icon { justify-content: center; transform: scale(1.2); color: rgb(0, 165, 240); padding: 0.5em; height: 100% !important; display: inline-flex !important; font-size: 96px !important; }
.card-icon { display: inline-flex; padding: 0.5em; text-align: center; margin: 0px auto; justify-content: center !important; max-width: 192px !important; }
.thumbnail { aspect-ratio: 16 / 9; margin-bottom: 1em; }
a.video-link, a.video-link h5, a.video-link h5:hover, a.video-link:hover h5 { text-decoration: none !important; color: var(--bg-fill-invert) !important; }
a.video-link h5, a.video-link h4 { color: rgb(134, 134, 139); }
body[data-color-scheme="dark"] a.video-link h5, body[data-color-scheme="dark"] a.video-link h4 { color: rgb(110, 110, 115); }
.tile-new-design { background-image: url("/design/images/sol/feature-new-design_2x.jpg"); }
body[data-color-scheme="light"] .tile-new-design button { filter: brightness(0.8); }
body[data-color-scheme="dark"] .tile-new-design .tile-category.lighter { color: rgb(129, 129, 129); }
body[data-color-scheme="dark"] .tile-new-design .typography-card-headline { color: rgb(29, 29, 31); }
.tile-whats-new { background: linear-gradient(to right bottom, rgb(169, 222, 247), rgb(231, 241, 255)); }
body[data-color-scheme="dark"] .tile-whats-new { background: linear-gradient(to right bottom, rgb(26, 74, 99), rgb(44, 62, 80)); }
.whats-new-icon { justify-content: center; padding-bottom: 1.5em; width: 150px !important; align-self: center !important; }
.tile-pathways { background: linear-gradient(rgb(0, 85, 199) 0%, rgb(0, 113, 227) 100%); }
.de-event-copy { margin-top: 1.5em; }
